var keyPattern = regexp.MustCompile(`^rb_live_([0-9a-f]{8})_[A-Z2-7]{26}$`)

type APIKey struct {
	ID         int64
	BuildingID int64
	Scopes     []string
}

func NewAPIKey() (key, prefix string) {
	b := make([]byte, 4)
	rand.Read(b)
	prefix = hex.EncodeToString(b)
	return "rb_live_" + prefix + "_" + rand.Text(), prefix
}

func keyHash(key string) []byte {
	sum := sha256.Sum256([]byte(key))
	return sum[:]
}

type APIKeyStore struct{ db DBTX }

func NewAPIKeyStore(db DBTX) *APIKeyStore { return &APIKeyStore{db: db} }

func (s *APIKeyStore) Create(ctx context.Context, name string, buildingID int64, scopes []string) (id int64, key, prefix string, err error) {
	key, prefix = NewAPIKey()
	err = s.db.QueryRow(ctx, `
		INSERT INTO api_keys (prefix, key_hash, name, building_id, scopes)
		VALUES ($1, $2, $3, $4, $5) RETURNING id`,
		prefix, hex.EncodeToString(keyHash(key)), name, buildingID, scopes,
	).Scan(&id)
	return id, key, prefix, err
}

func (s *APIKeyStore) Check(ctx context.Context, presented string) (APIKey, error) {
	m := keyPattern.FindStringSubmatch(presented)
	if m == nil {
		return APIKey{}, domain.ErrNotFound
	}
	var k APIKey
	var storedHex string
	err := s.db.QueryRow(ctx, `
		SELECT id, building_id, scopes, key_hash FROM api_keys
		 WHERE prefix = $1 AND revoked_at IS NULL`, m[1],
	).Scan(&k.ID, &k.BuildingID, &k.Scopes, &storedHex)
	if err != nil {
		return APIKey{}, domain.ErrNotFound
	}
	stored, _ := hex.DecodeString(storedHex)
	if subtle.ConstantTimeCompare(keyHash(presented), stored) != 1 {
		return APIKey{}, domain.ErrNotFound
	}
	_, err = s.db.Exec(ctx, `
		UPDATE api_keys SET last_used_at = now()
		 WHERE id = $1 AND (last_used_at IS NULL OR last_used_at < now() - interval '1 minute')`, k.ID)
	return k, err
}

func NewSSOHandler(ctx context.Context, issuer, clientID, clientSecret, redirectURL string) (*SSOHandler, error) {
	provider, err := oidc.NewProvider(ctx, issuer)
	if err != nil {
		return nil, err
	}
	return &SSOHandler{
		OAuth: oauth2.Config{
			ClientID:     clientID,
			ClientSecret: clientSecret,
			Endpoint:     provider.Endpoint(),
			RedirectURL:  redirectURL,
			Scopes:       []string{oidc.ScopeOpenID, "email", "profile"},
		},
		Verifier: provider.Verifier(&oidc.Config{ClientID: clientID}),
	}, nil
}

const ssoCookie = "__Host-sso"

func (h *SSOHandler) start(w http.ResponseWriter, r *http.Request) error {
	state, nonce, verifier := rand.Text(), rand.Text(), oauth2.GenerateVerifier()
	http.SetCookie(w, &http.Cookie{
		Name: ssoCookie, Value: state + "." + nonce + "." + verifier,
		Path: "/", MaxAge: 600, Secure: true, HttpOnly: true, SameSite: http.SameSiteLaxMode,
	})
	url := h.OAuth.AuthCodeURL(state, oauth2.S256ChallengeOption(verifier), oidc.Nonce(nonce))
	http.Redirect(w, r, url, http.StatusFound)
	return nil
}

func (h *SSOHandler) callback(w http.ResponseWriter, r *http.Request) error {
	c, err := r.Cookie(ssoCookie)
	parts := []string{}
	if err == nil {
		parts = strings.Split(c.Value, ".")
	}
	if len(parts) != 3 || r.URL.Query().Get("state") != parts[0] {
		return unauthorized("Start the sign-in again.")
	}
	nonce, verifier := parts[1], parts[2]

	token, err := h.OAuth.Exchange(r.Context(), r.URL.Query().Get("code"), oauth2.VerifierOption(verifier))
	if err != nil {
		return unauthorized("The sign-in didn't complete.")
	}
	raw, _ := token.Extra("id_token").(string)
	idToken, err := h.Verifier.Verify(r.Context(), raw)
	if err != nil || idToken.Nonce != nonce {
		return unauthorized("The sign-in didn't complete.")
	}
	var claims struct {
		Email         string `json:"email"`
		EmailVerified bool   `json:"email_verified"`
	}
	if err := idToken.Claims(&claims); err != nil {
		return err
	}
	userID, err := h.Identities.Link(r.Context(), idToken.Issuer, idToken.Subject, claims.Email, claims.EmailVerified)
	if err != nil {
		return err
	}
	http.SetCookie(w, &http.Cookie{Name: ssoCookie, Path: "/", MaxAge: -1, Secure: true, HttpOnly: true})
	if err := h.Auth.startSession(w, r, userID); err != nil {
		return err
	}
	http.Redirect(w, r, h.AppURL, http.StatusSeeOther)
	return nil
}

type IdentityStore struct{ db DBTX }

func NewIdentityStore(db DBTX) *IdentityStore { return &IdentityStore{db: db} }

// Link finds the user behind an issuer and subject, linking a staff
// account by its verified email the first time.
func (s *IdentityStore) Link(ctx context.Context, issuer, subject, email string, emailVerified bool) (int64, error) {
	var userID int64
	err := s.db.QueryRow(ctx,
		`SELECT user_id FROM oidc_identities WHERE issuer = $1 AND subject = $2`,
		issuer, subject).Scan(&userID)
	if err == nil {
		return userID, nil
	}
	if !errors.Is(err, pgx.ErrNoRows) {
		return 0, err
	}
	if !emailVerified || email == "" {
		return 0, ErrNotStaff
	}
	err = s.db.QueryRow(ctx,
		`SELECT id FROM users WHERE lower(email) = lower($1) AND role IN ('staff', 'admin')`,
		email).Scan(&userID)
	if errors.Is(err, pgx.ErrNoRows) {
		return 0, ErrNotStaff
	}
	if err != nil {
		return 0, err
	}
	_, err = s.db.Exec(ctx,
		`INSERT INTO oidc_identities (issuer, subject, user_id) VALUES ($1, $2, $3)`,
		issuer, subject, userID)
	return userID, err
}

// UniversityTokens checks access tokens the university issued for Roombook.
func UniversityTokens(ctx context.Context) (*oidc.IDTokenVerifier, error) {
	provider, err := oidc.NewProvider(ctx, "https://login.university.example")
	if err != nil {
		return nil, err
	}
	return provider.Verifier(&oidc.Config{
		ClientID:             "https://api.roombook.example",
		SupportedSigningAlgs: []string{oidc.RS256, oidc.ES256},
	}), nil
}

type Principal struct {
	Via        string // "session", "bearer", or "api-key"
	UserID     *int64
	Role       string
	BuildingID *int64
	Scopes     []string
}

func (p *Principal) HasScope(scope string) bool { return slices.Contains(p.Scopes, scope) }

var memberScopes = []string{"bookings:read", "bookings:write", "feedback:write"}
var staffScopes = append(slices.Clone(memberScopes), "rooms:write", "schedule:read", "api-keys:write")

var RoleScopes = map[string][]string{
	"member": memberScopes,
	"staff":  staffScopes,
	"admin":  append(slices.Clone(staffScopes), "rooms:delete", "webhooks:write"),
}

func UserPrincipal(via string, userID int64, role string, buildingID *int64, granted []string) *Principal {
	scopes := RoleScopes[role]
	if granted != nil {
		scopes = slices.DeleteFunc(slices.Clone(scopes), func(s string) bool { return !slices.Contains(granted, s) })
	}
	return &Principal{Via: via, UserID: &userID, Role: role, BuildingID: buildingID, Scopes: scopes}
}

func (a *Authenticator) principal(ctx context.Context, r *http.Request) (*auth.Principal, *domain.ProblemError) {
	if c, err := r.Cookie(sessionCookie); err == nil {
		u, err := a.Users.BySessionHash(ctx, auth.HashToken(c.Value))
		if err != nil {
			return nil, unauthorized("Your session has ended. Sign in again.")
		}
		return auth.UserPrincipal("session", u.ID, u.Role, u.BuildingID, nil), nil
	}
	if token, ok := strings.CutPrefix(r.Header.Get("Authorization"), "Bearer "); ok {
		claims, err := a.Tokens.Verify(token)
		if err != nil {
			return nil, unauthorized("The access token is invalid or expired.")
		}
		userID, err := strconv.ParseInt(claims.Subject, 10, 64)
		if err != nil {
			return nil, unauthorized("The access token is invalid or expired.")
		}
		return auth.UserPrincipal("bearer", userID, claims.Role, claims.BuildingID, strings.Fields(claims.Scope)), nil
	}
	if key := r.Header.Get("Api-Key"); key != "" {
		k, err := a.APIKeys.Check(ctx, key)
		if err != nil {
			return nil, unauthorized("The API key is invalid or revoked.")
		}
		return &auth.Principal{Via: "api-key", BuildingID: &k.BuildingID, Scopes: k.Scopes}, nil
	}
	return nil, nil
}

func (a *Authenticator) Middleware(next http.Handler) http.Handler {
	return http.HandlerFunc(func(w http.ResponseWriter, r *http.Request) {
		p, err := a.principal(r.Context(), r)
		if err != nil {
			writeProblem(w, r, err)
			return
		}
		if p != nil {
			r = r.WithContext(auth.WithPrincipal(r.Context(), p))
		}
		next.ServeHTTP(w, r)
	})
}

// GetVisible returns the booking only when p may see it: its owner,
// staff of its building, or an admin.
func (s *BookingStore) GetVisible(ctx context.Context, id int64, p *auth.Principal) (domain.Booking, error) {
	rows, _ := s.db.Query(ctx, `
		SELECT `+bookingColumns+` FROM bookings
		 WHERE id = $1
		   AND ($2 = 'admin'
		        OR user_id = $3
		        OR ($2 = 'staff' AND room_id IN (SELECT id FROM rooms WHERE building_id = $4)))`,
		id, p.Role, p.UserID, p.BuildingID)
	b, err := pgx.CollectExactlyOneRow(rows, scanBooking)
	if errors.Is(err, pgx.ErrNoRows) {
		return domain.Booking{}, fmt.Errorf("booking %d: %w", id, domain.ErrNotFound)
	}
	return b, err
}

